        d: p.d, at: p.at, base: p.base,
        f2: Object.fromEntries(Object.entries(p.f2 || {}).map(([k, v]) => [k, fstatSplit(v, 2)])),
        f3: Object.fromEntries(Object.entries(p.f3 || {}).map(([k, v]) => [k, fstatSplit(v, 3)]))
